using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Identity;
using System.ComponentModel.DataAnnotations;
namespace AttendanceApi.Models;

public static class Roles { public const string Admin = "Admin", Lecturer = "Lecturer", Student = "Student"; }
public enum AttendanceState { Scheduled, Open, Closed }
public enum AttendanceStatus { Present, Late, Absent, Excused }
public enum ChallengePurpose { VerifyEmail, Login }
public class ApplicationUser : IdentityUser { [MaxLength(150)] public string FullName { get; set; } = ""; public bool IsActive { get; set; } = true; }
public class Student { public int Id { get; set; } [MaxLength(40)] public string StudentCode { get; set; } = ""; [MaxLength(150)] public string FullName { get; set; } = ""; [MaxLength(256)] public string Email { get; set; } = ""; public string? UserId { get; set; } [JsonIgnore] public ApplicationUser? User { get; set; } }
public class Lecturer { public int Id { get; set; } [MaxLength(40)] public string LecturerCode { get; set; } = ""; [MaxLength(150)] public string FullName { get; set; } = ""; [MaxLength(256)] public string Email { get; set; } = ""; public string? UserId { get; set; } [JsonIgnore] public ApplicationUser? User { get; set; } }
public class Subject { public int Id { get; set; } [MaxLength(40)] public string Code { get; set; } = ""; [MaxLength(150)] public string Name { get; set; } = ""; }
public class Room { public int Id { get; set; } [MaxLength(40)] public string Code { get; set; } = ""; [MaxLength(150)] public string Name { get; set; } = ""; public double Latitude { get; set; } public double Longitude { get; set; } public double AllowedRadiusMeters { get; set; } }
public class CourseClass { public int Id { get; set; } [MaxLength(40)] public string Code { get; set; } = ""; [MaxLength(150)] public string Name { get; set; } = ""; public int SubjectId { get; set; } [JsonIgnore] public Subject Subject { get; set; } = null!; public int LecturerId { get; set; } [JsonIgnore] public Lecturer Lecturer { get; set; } = null!; }
public class Enrollment { public int CourseClassId { get; set; } [JsonIgnore] public CourseClass CourseClass { get; set; } = null!; public int StudentId { get; set; } [JsonIgnore] public Student Student { get; set; } = null!; }
public class ClassSession { public int Id { get; set; } public int CourseClassId { get; set; } [JsonIgnore] public CourseClass CourseClass { get; set; } = null!; public int RoomId { get; set; } [JsonIgnore] public Room Room { get; set; } = null!; public DateTimeOffset StartAtUtc { get; set; } public DateTimeOffset EndAtUtc { get; set; } public DateTimeOffset AttendanceClosesAtUtc { get; set; } public int LateAfterMinutes { get; set; } public AttendanceState AttendanceState { get; set; } public string? QrTokenHash { get; set; } public string? QrTokenProtected { get; set; } public DateTimeOffset? QrExpiresAtUtc { get; set; } }
public class Attendance { public int Id { get; set; } public int ClassSessionId { get; set; } [JsonIgnore] public ClassSession ClassSession { get; set; } = null!; public int StudentId { get; set; } [JsonIgnore] public Student Student { get; set; } = null!; public DateTimeOffset? CheckedInAtUtc { get; set; } public AttendanceStatus Status { get; set; } public double? Latitude { get; set; } public double? Longitude { get; set; } public double? AccuracyMeters { get; set; } public double? DistanceMeters { get; set; } }
public class AttendanceChangeLog { public int Id { get; set; } public int AttendanceId { get; set; } [JsonIgnore] public Attendance Attendance { get; set; } = null!; public string ChangedByUserId { get; set; } = ""; [JsonIgnore] public ApplicationUser ChangedByUser { get; set; } = null!; public DateTimeOffset ChangedAtUtc { get; set; } public AttendanceStatus PreviousStatus { get; set; } public AttendanceStatus NewStatus { get; set; } [MaxLength(1000)] public string Reason { get; set; } = ""; }
public class EmailChallenge { public Guid Id { get; set; } = Guid.NewGuid(); public string UserId { get; set; } = ""; [JsonIgnore] public ApplicationUser User { get; set; } = null!; public ChallengePurpose Purpose { get; set; } public string CodeHash { get; set; } = ""; public DateTimeOffset ExpiresAtUtc { get; set; } public DateTimeOffset ResendAvailableAtUtc { get; set; } public int FailedAttempts { get; set; } public bool Consumed { get; set; } public bool Delivered { get; set; } }
